#pragma once
// H(x) is canonically defined in RenderSystem/Defines.h and is available via
// the forced include once the Sharpmake-generated project is regenerated.
// Retained here because passes.ixx does `export import "../defines.h"` and the
// autogenerated pass headers rely on H being visible through that import.
// The #ifndef guard prevents a redefinition once the forced include is active.
#ifndef H
#  define H(x) x = #x
#endif
